import type { ServerBuild } from '@remix-run/cloudflare';
import { createPagesFunctionHandler } from '@remix-run/cloudflare-pages';
import { checkAccess } from '../app/lib/.server/security';

// @ts-ignore because the server build file is generated by `remix vite:build`
import * as serverBuild from '../build/server';

const handleRequest = createPagesFunctionHandler({
  build: serverBuild as unknown as ServerBuild,
});

export const onRequest: PagesFunction<Env> = (context) => {
  // protect every server-rendered page, not only the API routes, so the browser asks for credentials on load
  const denied = checkAccess(context.request, {
    password: context.env.BOLT_ACCESS_PASSWORD,
    username: context.env.BOLT_ACCESS_USER,
  });

  if (denied) {
    return denied;
  }

  return handleRequest(context);
};
